UPDATE bt_skill_flow
SET flow_graph_json = #{flow.flowGraphJson},
    flow_dsl = #{flow.flowDsl}
WHERE flow_id = #{flow.flowId}
  AND tenant_id = #{flow.tenantId}
  AND status_cd = '00A'

